" 2>/dev/null || python3 << 'EOF'
import openpyxl
wb = openpyxl.load_workbook('sales_data.xlsx')
for ws in wb.worksheets:
    print('Sheet:', ws.title, 'dims:', ws.dimensions, 'max_row:', ws.max_row, 'max_col:', ws.max_column)
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 10)):
        for cell in row:
            if cell.value is not None:
                print(f'  {cell.coordinate}: {repr(cell.value)}')
EOF

